import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"TMPA V1.0 Release Readiness Audit — RA1","description":"","frontmatter":{"title":"TMPA V1.0 Release Readiness Audit — RA1","type":"release-audit","domain":"TMPA","version":"RA1","status":"blocked","source":"github-main","outline":"deep"},"headers":[],"relativePath":"en/publications/tmpa-v1.0-release-readiness-audit.md","filePath":"en/publications/tmpa-v1.0-release-readiness-audit.md","lastUpdated":1786355271000}'),r={name:"en/publications/tmpa-v1.0-release-readiness-audit.md"};function s(o,e,d,c,l,p){return t(),i("div",null,[...e[0]||(e[0]=[n(`<h1 id="tmpa-v1-0-release-readiness-audit" tabindex="-1">TMPA V1.0 Release Readiness Audit <a class="header-anchor" href="#tmpa-v1-0-release-readiness-audit" aria-label="Permalink to &quot;TMPA V1.0 Release Readiness Audit&quot;">​</a></h1><p><strong>Audit date:</strong> 2026-08-10<br><strong>Frozen audit baseline:</strong> <code>8e01c275062244d4978539f86399853f2e35b0e5</code><br><strong>Versions reviewed:</strong> Main Paper A0.9 · Core Specification S0.6 · Implementation Case I0.8<br><strong>Promotion decision:</strong> <strong>BLOCKED</strong></p><p>The three-document system is coherent enough to enter release remediation, and its current engineering evidence passes. It is not yet ready to be relabeled A1.0, S1.0 and I1.0. The blockers are release-governance and archival gaps, not a failed TMPA theory claim or a failed C01–C14 product run.</p><p>No V1.0 version label, Git tag, DOI or stable-release claim SHALL be issued until every P0 item below is closed in Git history.</p><h2 id="_1-scope-and-decision-model" tabindex="-1">1. Scope and decision model <a class="header-anchor" href="#_1-scope-and-decision-model" aria-label="Permalink to &quot;1. Scope and decision model&quot;">​</a></h2><p>This audit checks the GitHub single source of truth only. It does not treat a local editor folder, ChatGPT Library, unpublished working directory or historical copy as an official source.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th><th>Finding</th></tr></thead><tbody><tr><td>Three-document separation</td><td>PASS</td><td>A0.9 is theory, S0.6 is normative specification, and I0.8 is bounded engineering evidence.</td></tr><tr><td>English/Chinese structural parity</td><td>PASS</td><td>Matching heading counts: Main 17 H1 / 35 H2; Core 14 H1 / 54 H2; Case 16 H1 / 6 H2.</td></tr><tr><td>Terminology and guidance chain</td><td>PASS</td><td>The current relation is consistently stated as TMPA theory → Core requirements → FCoP coordination protocol → CodeFlowMu implementation evidence.</td></tr><tr><td>Core criteria integrity</td><td>PASS</td><td>Both languages contain C01–C14; the Reference Reader passes 14/14.</td></tr><tr><td>Product evidence integrity</td><td>PASS</td><td>CodeFlowMu V1.6.0 against S0.6 reports 14 PASS, 0 PARTIAL, 0 NOT RUN and 0 FAIL.</td></tr><tr><td>Evidence archive integrity</td><td>PASS</td><td>ZIP checksum and archive integrity pass; the public reproducer contains 195 entries.</td></tr><tr><td>Reference identity sample</td><td>PASS</td><td>Nine high-change arXiv records were checked against their live records; identifier and title pairs match.</td></tr><tr><td>Release dossier consistency</td><td>BLOCKED</td><td>The frozen S0.6 audit and informative Core text still state that no S0.6 product run exists.</td></tr><tr><td>Archival source fixation</td><td>BLOCKED</td><td>The CodeFlowMu browser evidence and XiaoDian AI archive are not yet fixed as stable public submission artifacts.</td></tr><tr><td>V1.0 publication package</td><td>BLOCKED</td><td>TMPA-specific citation metadata, author identifiers, release manifest, release notes and submission artifacts are incomplete.</td></tr></tbody></table><p>The final decision is therefore <strong>BLOCKED for V1.0 promotion</strong>, while the current A0.9/S0.6/I0.8 engineering baseline remains valid.</p><h2 id="_2-reproducibility-record" tabindex="-1">2. Reproducibility record <a class="header-anchor" href="#_2-reproducibility-record" aria-label="Permalink to &quot;2. Reproducibility record&quot;">​</a></h2><h3 id="_2-1-s0-6-reference-reader" tabindex="-1">2.1 S0.6 Reference Reader <a class="header-anchor" href="#_2-1-s0-6-reference-reader" aria-label="Permalink to &quot;2.1 S0.6 Reference Reader&quot;">​</a></h3><p><code>npm run tmpa:s0.6:conformance</code> completed with <strong>14/14 PASS</strong>. The result digest was:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sha256:210ae9ca94235a4886cb67e633769d0709a7ae9fe54771226eee528d067a1c51</span></span></code></pre></div><p>Its product track is an intentionally frozen historical <code>NOT RUN</code> baseline. That history SHALL remain unchanged; I0.8 must instead be registered as a later, external exact-version product run.</p><h3 id="_2-2-i0-8-public-evidence-package" tabindex="-1">2.2 I0.8 public evidence package <a class="header-anchor" href="#_2-2-i0-8-public-evidence-package" aria-label="Permalink to &quot;2.2 I0.8 public evidence package&quot;">​</a></h3><p>Audited artifact:</p><ul><li><a href="/joinwell52/evidence/tmpa/i0.8/tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip">I0.8 CodeFlowMu V1.6.0 / S0.6 evidence ZIP</a></li></ul><p>The adjacent file <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip.sha256</code> records the checksum below.</p><p>Verified archive digest:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</span></span></code></pre></div><p><code>sha256sum -c</code>, ZIP integrity, the seven canonical LF input checks and the product runner all passed. The product runner returned:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>aggregate: PASS</span></span>
<span class="line"><span>PASS: 14</span></span>
<span class="line"><span>PARTIAL: 0</span></span>
<span class="line"><span>NOT RUN: 0</span></span>
<span class="line"><span>FAIL: 0</span></span>
<span class="line"><span>product_reader_called: true</span></span>
<span class="line"><span>reference_reader_called: false</span></span>
<span class="line"><span>input_bundle_digest: sha256:251914ee55922d20c9bd23943a4ff445bccaa5835e1fcc11b8562f3f384243fa</span></span>
<span class="line"><span>result_digest: sha256:f16ab28e694003a25ba83cb9c94e85d757860201caca2f489f32e4d1ca3cc7f2</span></span></code></pre></div><p>The packaged <code>tsx</code> launcher could not open its temporary IPC socket inside this review sandbox (<code>EPERM</code>). After dependency installation from the canonical npm registry and successful input verification, the same TypeScript runner was executed with Node&#39;s type-stripping mode and produced the recorded result above. This is an environment limitation, not a failed conformance assertion; an unrestricted clean-machine rerun remains part of release packaging.</p><h2 id="_3-p0-blockers" tabindex="-1">3. P0 blockers <a class="header-anchor" href="#_3-p0-blockers" aria-label="Permalink to &quot;3. P0 blockers&quot;">​</a></h2><h3 id="p0-01-—-register-the-later-s0-6-product-run" tabindex="-1">P0-01 — Register the later S0.6 product run <a class="header-anchor" href="#p0-01-—-register-the-later-s0-6-product-run" aria-label="Permalink to &quot;P0-01 — Register the later S0.6 product run&quot;">​</a></h3><p>The historical S0.6 release audit and informative Core text still say that no exact S0.6 product evidence exists. Preserve the frozen Reference Reader record, add a dated external-run registration for I0.8, and remove the now-stale prospective wording from both Core language editions.</p><p><strong>Closure evidence:</strong> bilingual Core correction, external-run manifest entry, exact evidence path, checksum, execution identity and a Git commit.</p><h3 id="p0-02-—-freeze-the-cited-implementation-sources" tabindex="-1">P0-02 — Freeze the cited implementation sources <a class="header-anchor" href="#p0-02-—-freeze-the-cited-implementation-sources" aria-label="Permalink to &quot;P0-02 — Freeze the cited implementation sources&quot;">​</a></h3><p>Main Paper reference [13] says the CodeFlowMu browser build and dataset identity still need fixation. Reference [25] says XiaoDian AI requires a fixed public or archival snapshot before external submission. Either publish immutable snapshots with commit/tag and archive identifiers, or narrow/remove the dependent submission claims.</p><p><strong>Closure evidence:</strong> stable public URLs, repository commit/tag identities, archive checksums and explicit claim boundaries.</p><h3 id="p0-03-—-create-tmpa-specific-citation-metadata" tabindex="-1">P0-03 — Create TMPA-specific citation metadata <a class="header-anchor" href="#p0-03-—-create-tmpa-specific-citation-metadata" aria-label="Permalink to &quot;P0-03 — Create TMPA-specific citation metadata&quot;">​</a></h3><p>The repository-level <code>CITATION.cff</code> describes joinwell52 Research Center 3.0, not the TMPA three-document release. Each V1.0 document needs a canonical title, author list, affiliation, version, release date, repository URL, license, preferred citation and DOI field. English and Chinese editions must point to the same work identity while retaining independent language metadata.</p><p><strong>Closure evidence:</strong> validated TMPA CFF/BibTeX metadata and synchronized document frontmatter.</p><h3 id="p0-04-—-build-the-immutable-v1-0-release-package" tabindex="-1">P0-04 — Build the immutable V1.0 release package <a class="header-anchor" href="#p0-04-—-build-the-immutable-v1-0-release-package" aria-label="Permalink to &quot;P0-04 — Build the immutable V1.0 release package&quot;">​</a></h3><p>The repository has web Markdown but no complete TMPA V1.0 release dossier. Produce submission-ready artifacts, a file manifest with SHA-256 values, bilingual release notes and a reproducible build record. The final tag must be created only from the reviewed commit.</p><p><strong>Closure evidence:</strong> reproducible paper artifacts, manifest, checksums, release notes, clean CI and the reviewed release commit. Tag and DOI creation occur after the package passes review.</p><h2 id="_4-p1-release-decisions" tabindex="-1">4. P1 release decisions <a class="header-anchor" href="#_4-p1-release-decisions" aria-label="Permalink to &quot;4. P1 release decisions&quot;">​</a></h2><p>These require the author&#39;s explicit confirmation before public release:</p><ol><li>canonical author name, affiliation, public contact address and ORCID;</li><li>the license for papers, specification and evidence artifacts—the current repository notice is all-rights-reserved with limited academic reading and citation permission;</li><li>Zenodo deposit structure and DOI backfill sequence;</li><li>submission venue packaging, including any venue-specific anonymous or source archive.</li></ol><h2 id="_5-findings-that-do-not-block-a-bounded-v1-0" tabindex="-1">5. Findings that do not block a bounded V1.0 <a class="header-anchor" href="#_5-findings-that-do-not-block-a-bounded-v1-0" aria-label="Permalink to &quot;5. Findings that do not block a bounded V1.0&quot;">​</a></h2><p>Independent rerun, independent adoption, comparative baselines, representative SME operating-cost measurements and broader low-resource performance remain open research work. They do not block V1.0 if the documents continue to label the current result as author-run, avoid generalizing one implementation into proof of the theory, and preserve <code>Specified / Implemented / Demonstrated / Independently Adopted</code> as distinct states.</p><h2 id="_6-promotion-rule-and-next-gate" tabindex="-1">6. Promotion rule and next gate <a class="header-anchor" href="#_6-promotion-rule-and-next-gate" aria-label="Permalink to &quot;6. Promotion rule and next gate&quot;">​</a></h2><p>The publication cards remain <strong>A0.9 / S0.6 / I0.8</strong>. Phase 5.2 should close P0-01 through P0-04 without changing those labels. After the closure commit passes bilingual checks, conformance verification, evidence checksum verification and site build, a final promotion review may authorize <strong>A1.0 / S1.0 / I1.0</strong>, the release tag and archival deposit.</p><p>This audit itself is an official revision only after its Git commit is present on the default branch.</p>`,43)])])}const m=a(r,[["render",s]]);export{u as __pageData,m as default};
